function RoadmapEntry({ item }) {
  const { label, dates, title, summary, unlocks, milestone, labelVariant } = item
  const isMilestoneLabel = labelVariant === "milestone"

  return (
    <div className="relative sm:grid sm:grid-cols-[13rem_4rem_minmax(0,1fr)] sm:items-start">
      <div className="relative z-10 mb-4 sm:mb-0 sm:flex sm:justify-end sm:pr-4 sm:pt-3">
        {isMilestoneLabel ? (
          <span className={timelineMilestoneClass}>{label}</span>
        ) : (
          <span className={timelineLabelClass}>{label}</span>
        )}
      </div>

      <div className="hidden sm:flex sm:justify-center sm:pt-10">
        <span className={`${timelineDotClass} bg-brand-surface-hover`}></span>
      </div>

      <div
        className={`absolute left-[-2rem] top-9 ${timelineDotClass} bg-brand-surface-hover sm:hidden`}
      ></div>

      <article className={articleClass}>
        <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-line to-transparent"></div>

        <div>
          <p className="text-small font-semibold uppercase tracking-wide text-muted">{dates}</p>
          <div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <h2 className="text-title font-semibold tracking-normal text-inverse">{title}</h2>
            {milestone && <span className={milestoneClass}>{milestone}</span>}
          </div>
          <p className="mt-4 text-lead leading-relaxed text-inverse-muted">{summary}</p>
        </div>

        <p className="mt-6 text-body leading-relaxed text-inverse">
          <span className="font-semibold text-brand-light">What it unlocks:</span> {unlocks}
        </p>
      </article>
    </div>
  )
}

function ContentSection({ title, description, children }) {
  return (
    <section className={contentSectionClass}>
      <div>
        <h2 className={sectionHeadingClass}>{title}</h2>
        <p className={sectionDescriptionClass}>{description}</p>
      </div>
      {children}
    </section>
  )
}

function ContentCard({ title, children }) {
  return (
    <article className={contentCardClass}>
      <h3 className={cardHeadingClass}>{title}</h3>
      {children}
    </article>
  )
}

function LatestNews({ edges }) {
  return (
    <div className="mt-16">
      <div className="flex items-center justify-between gap-4">
        <h3 className={cardHeadingClass}>Latest News</h3>
        <Link to="/news" className={newsLinkClass}>
          View All News
        </Link>
      </div>

      <div className="mt-8">
        <NewsList
          edges={edges}
          limit={3}
          listClassName="grid gap-6 lg:grid-cols-3"
          itemClassName=""
        />
      </div>
    </div>
  )
}

export default function Roadmap({ data }) {
  return (
    <Layout>
      <div className="bg-dark">
        <Clamp>
          <section className="px-4 py-24 text-inverse-muted">
            <div>
              <h1 className="mb-6 text-display font-bold tracking-normal text-inverse sm:text-display">
                Crown 2026 Roadmap
              </h1>
              <p className="mb-24 text-lead text-inverse-muted">
                A timeline of the next major milestones on the road to Crown 1.0.
              </p>
            </div>

            <div className="relative mx-auto max-w-5xl pl-10 sm:pl-0 sm:pr-28 lg:pr-48">
              <div className="absolute bottom-0 left-4 top-0 w-px bg-brand-surface-hover sm:left-[15rem]"></div>

              <div className="space-y-8">
                {roadmapItems.map(item => (
                  <RoadmapEntry key={item.title} item={item} />
                ))}
              </div>
            </div>

            <ContentSection
              title="Road to 1.0"
              description="Crown 1.0 aims to make the engine production-ready for smaller-scope commercial games."
            >
              <div className="mt-10 grid gap-6 md:grid-cols-2">
                {roadToOneItems.map(({ question, answer }) => (
                  <ContentCard key={question} title={question}>
                    <p className={roadToOneBodyClass}>{answer}</p>
                  </ContentCard>
                ))}
              </div>
            </ContentSection>

            <ContentSection
              title="Recent Progress"
              description="Crown has accelerated sharply over the last year, with a higher release pace, broader engine capabilities, and continued momentum into 2026."
            >
              <div className="mt-10 space-y-6">
                {recentProgressItems.map(({ title, body }) => (
                  <ContentCard key={title} title={title}>
                    {body}
                  </ContentCard>
                ))}
              </div>
              <LatestNews edges={data.allMdx.edges} />
            </ContentSection>
          </section>
        </Clamp>
      </div>
    </Layout>
  )
}

export const pageQuery = graphql`
  query {
    allMdx(sort: { frontmatter: { date: DESC } }, limit: 3) {
      edges {
        node {
          id
          frontmatter {
            date(formatString: "MMMM DD, YYYY")
            slug
            title
            image {
              childImageSharp {
                gatsbyImageData(width: 1280, placeholder: DOMINANT_COLOR)
              }
            }
          }
          excerpt(pruneLength: 120)
        }
      }
    }
  }
`

export const Head = () => (
  <Seo
    title="Crown 2026 Roadmap"
    description="Upcoming Crown Engine milestones from Q2 2026 through Q1 2027."
  />
)
